import{_ as e,c as t,o,a2 as r}from"./chunks/framework.CzULAunO.js";const c=JSON.parse('{"title":"计算机科学与技术专业的几种出路","description":"","frontmatter":{"authors":["mekomimi"],"date":{"created":"2025-07-30T00:00:00.000Z"},"tags":["计算机科学与技术","CS"],"layout":"blog"},"headers":[],"relativePath":"docs/blog/posts/future-paths-for-cs-students.md","filePath":"docs/blog/posts/future-paths-for-cs-students.md","lastUpdated":1766652908000}'),l={name:"docs/blog/posts/future-paths-for-cs-students.md"};function s(p,a,i,d,n,h){return o(),t("div",null,a[0]||(a[0]=[r('<h1 id="计算机科学与技术专业的几种出路" tabindex="-1">计算机科学与技术专业的几种出路 <a class="header-anchor" href="#计算机科学与技术专业的几种出路" aria-label="Permalink to &quot;计算机科学与技术专业的几种出路&quot;">​</a></h1><p>计算机科学与技术专业（Computer and Science, CS）的出路与其他专业大同小异，主要有以下几种：保研、考研、工作、编制（公务员、事业编制等），以及一些小众的出路。</p><p>这篇文章是面向普通学生的，也就是没有竞赛保送、学术资源或导师带飞的普通人。</p><h2 id="保研" tabindex="-1">保研 <a class="header-anchor" href="#保研" aria-label="Permalink to &quot;保研&quot;">​</a></h2><p>辅导员一言堂，不太公开透明。需要和辅导员打好关系（一般就是当学生干部替导员干活），再参考自己学院的保研加分项，每一项都要完成得比较好，一般就是绩点，竞赛，科研，学生干部，学校活动（三下乡，运动会，各种征文，志愿者之类的）。</p><ul><li>绩点，就是成绩要好，成绩是平时分和期末成绩的加权计算。平时分就是注意小作业什么的都要过量完成，一般要和任课老师多交流。期末就是普通考试，做往年卷子，各种复习什么的。</li><li>竞赛，一般各种各样的比赛都能加分，这其实是缺点，因为水比赛对专业没用，但是别人参加，你不参加就会被落下。（计算机有含金量的竞赛，只有 ICPC 这种顶级比赛，但那个难度恐怕卷保研的普通人是拿不了奖的）。</li><li>科研，就是进实验室发论文，这个上课多提问，或者当课代表，和任课老师打好关系，可以问问能不能进老师的课题组。</li><li>学生干部，就是班长和团支书什么的，需要帮辅导员干杂活。（并不能锻炼能力，只有决策者才能锻炼能力，打杂是锻炼不了的）</li><li>三下乡：面子活动，而且需要竞争才能拿奖。大部分人就是混一个参加表，只有想保研的人才会卷。</li></ul><p>优点是大四保研后可以空出一年空闲时间，而且保研其实比考研简单，因为计算机考研题目的难度是非常大的，但是平常期末考试比较简单，比考研更容易能考出好成绩。假如对钻研计算机知识没什么热情，只想拿个文凭，保研非常合适。另外平时和任课老师打好关系，更容易发论文和拿到推荐信，进学术圈有好处。</p><p>缺点是保研加分通常有很多与专业知识无关的东西，可能会分散精力。假如遇到性格差，能力不行的导员，可能会比较折磨。如果差一点没保上研，那就前功尽弃，因为保研加分项对工作用处不大，而考研仓促准备是考不上好学校的。</p><h2 id="考研" tabindex="-1">考研 <a class="header-anchor" href="#考研" aria-label="Permalink to &quot;考研&quot;">​</a></h2><p>计算机一般考 408，好一点的学校就是数一英一 408，这个考试难度在所有考研科目中是顶级难度。还有四六级一定要过，一般考研复试的要求四六级必须过，有些是四级必须过，好一点的院校就是六级必须过。</p><p>对于普通人而言，只有保持三年的高效学习，才能考上重点院校，对自我管理生活的能力要求非常高，其余就是纯考试技巧了。</p><p>最好也有些科研经历，复试有用，英语好复试也加分，四六级最好刷得分高点。</p><p>笔者所在的是一所排名前一百的普通本科，上岸率接近 20%，能上 985 的只有不到五人，还不是特别好的系所和专业，比较冷门，不好找工作。绝大部分人考上的就是上了一个双非的研究生，没考上的就二战了。</p><p>优点是对于部分本科出身较弱的同学，是一次逆袭机会。</p><h2 id="工作" tabindex="-1">工作 <a class="header-anchor" href="#工作" aria-label="Permalink to &quot;工作&quot;">​</a></h2><p>工作的难度不比考研低，首先要刷算法题，学习氛围和题库最好的是 leetCode 这个网站，每天吃透一道题就足够了，然后参加周赛。最好参加 ACM 竞赛，对找工作帮助非常大，学校一般都有 ACM 实验室，专门参加算法竞赛的，大一招新就加入。</p><p>假如要进大厂，需要从大二开始就准备实习，去牛客，或者 leetCode 找那些实习内推的帖子，寒暑假一定要去实习。另外还要背八股文。即使不是大厂，一般也都要求至少一段实习经历。</p><p>这里要点名一个报名费 300 块，名字是三个字的算法竞赛，找工作就没人认这个比赛，但是学校还一直宣传这个比赛，很难不怀疑背后有什么 py 交易。</p><p>关于辅导班，有些毕业找不到工作会去技术培训班，或者在校也参加，最好不要去，只要搜搜就知道有多少坑。</p><p>这个的好处就是毕业就能直接工作，而且大厂工资很高，也能积累工作经验，对计算机专业来讲非常重要。另外，即使是研究生，也需要走这个流程，和本科找工作是一样的。</p><p>坏处就是万一就业形势不行，即使你很厉害也可能找不到工作。不过这基本上都是自我成长的过程，就算没工作，也能学到技术。</p><h2 id="编制" tabindex="-1">编制 <a class="header-anchor" href="#编制" aria-label="Permalink to &quot;编制&quot;">​</a></h2><p>考公，考编之类的，与专业不相关，这里不再赘述。</p><h2 id="其它小众出路" tabindex="-1">其它小众出路 <a class="header-anchor" href="#其它小众出路" aria-label="Permalink to &quot;其它小众出路&quot;">​</a></h2><ul><li>创业（不要轻易尝试）</li><li>独立开发（需要有商业思维）</li></ul>',25)]))}const f=e(l,[["render",s]]);export{c as __pageData,f as default};
